<?php
$config=require __DIR__.'/config.php';date_default_timezone_set($config['timezone']??'America/Sao_Paulo');if(session_status()!==PHP_SESSION_ACTIVE)session_start(['cookie_httponly'=>true,'cookie_samesite'=>'Lax','use_strict_mode'=>true]);require_once __DIR__.'/lib/db.php';require_once __DIR__.'/lib/schema.php';require_once __DIR__.'/lib/functions.php';
$error='';$success='';$pdo=null;$adminCount=0;try{$pdo=db();migrate_database($pdo);$adminCount=(int)$pdo->query('SELECT COUNT(*) FROM admins')->fetchColumn();}catch(Throwable $e){$error=$e->getMessage();}
if($_SERVER['REQUEST_METHOD']==='POST'&&$pdo){verify_csrf();$adminName=trim($_POST['name']??'');$email=trim($_POST['email']??'');$password=(string)($_POST['password']??'');$brandName=trim($_POST['site_name']??'');$city=trim($_POST['site_city_state']??'');if($adminCount>0){$error='O sistema já possui administrador. Acesse o painel.';}elseif($adminName===''||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($password)<10||$brandName===''){$error='Informe nome da marca, administrador, e-mail válido e senha com pelo menos 10 caracteres.';}else{try{$pdo->prepare('INSERT INTO admins(name,email,password_hash,role,active) VALUES(?,?,?,"admin",1)')->execute([$adminName,$email,password_hash($password,PASSWORD_DEFAULT)]);ensure_brand_defaults();set_app_setting('site_name',$brandName);set_app_setting('smtp_from_name',$brandName);if($city!=='')set_app_setting('site_city_state',$city);set_app_setting('payment_mode','manual');if((int)$pdo->query('SELECT COUNT(*) FROM events')->fetchColumn()===0){$eventDate=(new DateTime('+21 days'))->setTime(22,0)->format('Y-m-d H:i:s');$pdo->prepare('INSERT INTO events(title,slug,description,event_date,doors_time,venue,address,status,vip_enabled,vip_capacity,sales_start,sales_end,minimum_age,max_tickets_per_order) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?)')->execute(['Evento de demonstração','evento-de-demonstracao','Este é um evento de demonstração. Edite ou exclua pelo painel administrativo.',$eventDate,'20:00',$brandName,app_setting('address',$config['address']??''),'published',1,150,date('Y-m-d H:i:s'),(new DateTime('+21 days'))->setTime(21,30)->format('Y-m-d H:i:s'),18,8]);$eventId=(int)$pdo->lastInsertId();$pdo->prepare('INSERT INTO ticket_types(event_id,name,description,price,stock,sort_order,active) VALUES(?,?,?,?,?,?,1)')->execute([$eventId,'Pista','Ingresso individual',40,300,1]);$pdo->prepare('INSERT INTO ticket_types(event_id,name,description,price,stock,sort_order,active) VALUES(?,?,?,?,?,?,1)')->execute([$eventId,'Camarote','Área diferenciada',80,100,2]);}audit_log('system.installed');$success='Instalação concluída. Agora personalize logo, fotos, textos e integrações no painel.';$adminCount=1;}catch(Throwable $e){$error='Não foi possível concluir a instalação: '.$e->getMessage();}}}
?>
<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Instalação • Cactus Eventos</title><link rel="stylesheet" href="assets/css/site.css"></head><body class="install-page"><main class="install-card"><img src="assets/media/placeholder-logo.svg" alt="Sua logo" class="install-logo"><span class="eyebrow dark">CACTUS EVENTOS • WHITE LABEL</span><h1>Instalação</h1><p>Site institucional + eventos + ingressos + Mercado Pago + Lista VIP + QR Code + portaria digital.</p><?php if($error):?><div class="alert error"><?=e($error)?></div><p><a class="btn btn-secondary" href="diagnostico.php">Abrir diagnóstico</a></p><?php endif;?><?php if($success):?><div class="alert success"><?=e($success)?></div><p><a class="btn btn-primary" href="admin/settings.php">Personalizar agora</a> <a class="btn btn-ghost dark-outline" href="index.php">Abrir site</a></p><?php elseif($adminCount>0):?><div class="alert success">Sistema instalado e banco atualizado.</div><p><a class="btn btn-primary" href="admin/login.php">Entrar no painel</a> <a class="btn btn-secondary" href="diagnostico.php">Diagnóstico</a></p><?php elseif(!$error):?><form method="post" class="form-grid one"><?=csrf_field()?><label>Nome da marca / casa<input name="site_name" required placeholder="Ex.: Arena 360"></label><label>Cidade / UF<input name="site_city_state" placeholder="Ex.: Bauru / SP"></label><label>Nome do administrador<input name="name" required autocomplete="name"></label><label>E-mail do administrador<input name="email" type="email" required autocomplete="email"></label><label>Senha<input name="password" type="password" minlength="10" required autocomplete="new-password"></label><button class="btn btn-primary" type="submit">Concluir instalação</button></form><?php endif;?><p class="powered-cactus">Produto Cactus • pronto para personalização por cliente</p></main></body></html>
